/**
 * Hard boundary: the sweeper never links to, reads from or writes to an internal
 * tool. It reads public procurement pages and nothing else.
 *
 * "Internal tool" means anything a company runs its work in: ticketing and wiki
 * (Jira, Confluence), CRM (Salesforce, Certinia, HubSpot), Microsoft 365
 * (SharePoint, Teams, Outlook, OneDrive, Dynamics / Business Central), Slack,
 * Google Workspace, helpdesks, work managers, call recorders — and any private
 * or intranet address. Findings and action items live only in the local ledger,
 * the Excel workbook and the dashboard.
 *
 * Enforced in four places:
 *   1. every outbound fetch, and every redirect hop, goes through assertAllowedUrl()
 *   2. a finding whose link points at a blocked host has the link removed
 *   3. scripts/validate.mjs scans all config, data and generated workflows with
 *      findBlocked() and fails CI on any hit
 *   4. the Claude Code agent definition grants no MCP / connector tools at all
 *
 * A tenant can block more hosts with guard.extraBlockedHosts; it cannot unblock these.
 *
 * Import-free on purpose: build-workflows.mjs inlines it into the n8n Code nodes.
 */

const INTERNAL_TOOL_DOMAINS = [
  // Atlassian
  "atlassian.net", "atlassian.com", "jira.com", "bitbucket.org", "statuspage.io", "trello.com",
  // CRM / PSA
  "salesforce.com", "force.com", "salesforce-sites.com", "visualforce.com", "certinia.com", "financialforce.com",
  "hubspot.com", "hubapi.com", "hs-sites.com", "dynamics.com", "zoho.com", "pipedrive.com",
  // Microsoft 365
  "sharepoint.com", "sharepoint-df.com", "office.com", "office.net", "office365.com", "microsoft365.com",
  "teams.microsoft.com", "teams.live.com", "outlook.com", "outlook.office.com", "outlook.office365.com",
  "onedrive.live.com", "1drv.ms", "graph.microsoft.com", "powerbi.com", "powerapps.com", "powerautomate.com",
  "businesscentral.dynamics.com", "login.microsoftonline.com", "azurewebsites.net",
  // Google Workspace
  "docs.google.com", "drive.google.com", "sheets.google.com", "slides.google.com", "mail.google.com",
  "calendar.google.com", "chat.google.com", "sites.google.com",
  // Chat, work management, docs
  "slack.com", "slack-edge.com", "notion.so", "notion.site", "monday.com", "asana.com", "clickup.com",
  "airtable.com", "smartsheet.com", "coda.io", "box.com", "dropbox.com", "miro.com", "lucid.app", "loom.com",
  // Helpdesk / ITSM
  "freshdesk.com", "freshservice.com", "zendesk.com", "servicenow.com", "service-now.com",
  // Sales tooling
  "sybill.ai", "clay.com", "gong.io", "outreach.io", "salesloft.com", "zoominfo.com", "docusign.net", "docusign.com",
  // Automation consoles
  "n8n.cloud", "zapier.com", "make.com",
];

const INTERNAL_HOST_PATTERNS = [
  /(^|\.)jira\./i,
  /(^|\.)confluence\./i,
  /(^|\.)wiki\./i,
  /(^|\.)intranet\./i,
  /\.(local|localhost|internal|intranet|corp|lan|home|private)$/i,
  /^localhost$/i,
  /^127\./, /^10\./, /^192\.168\./, /^172\.(1[6-9]|2\d|3[01])\./, /^169\.254\./, /^0\./,
  /^\[(::1|::ffff:|f[cd][0-9a-f]{0,2}:|fe80:)/i,
];

const INTERNAL_PATHS = [/\/wiki\/spaces\//i, /\/rest\/api\/\d+\/issue/i, /\/browse\/[A-Z][A-Z0-9]+-\d+/, /\/lightning\/r\//i, /\/sites\/[^/]+\/_layouts\//i];

function hostBlocked(host, extra) {
  const h = String(host).toLowerCase().replace(/\.$/, "");
  const domains = [...INTERNAL_TOOL_DOMAINS, ...(extra ?? [])].map((d) => String(d).toLowerCase());
  if (domains.some((d) => h === d || h.endsWith(`.${d}`))) return `${h} is an internal tool`;
  if (INTERNAL_HOST_PATTERNS.some((re) => re.test(h))) return `${h} is a private or intranet address`;
  if (!h.includes(".")) return `${h} is a single-label intranet host`;
  return null;
}

/** Why a URL is refused, or null if it is a public page the sweeper may read. */
function blockedReason(url, extraBlockedHosts = []) {
  let u;
  try { u = new URL(String(url)); } catch (e) { return null; }
  if (!/^https?:$/.test(u.protocol)) return `${u.protocol} links are not allowed`;
  const byHost = hostBlocked(u.hostname, extraBlockedHosts);
  if (byHost) return byHost;
  if (INTERNAL_PATHS.some((re) => re.test(u.pathname))) return `${u.pathname} looks like an internal-tool path`;
  return null;
}

function assertAllowedUrl(url, extraBlockedHosts = []) {
  const why = blockedReason(url, extraBlockedHosts);
  if (why) throw new Error(`Blocked: ${why}. The sweeper does not link to or read internal tools.`);
  return url;
}

/** A link that may be stored and shown, or null. Used on every finding. */
function safeLink(url, extraBlockedHosts = []) {
  return url && !blockedReason(url, extraBlockedHosts) ? url : null;
}

/** Walk any JSON value and return every URL in it that points at an internal tool. */
function findBlocked(value, where = "$", extraBlockedHosts = []) {
  const hits = [];
  const walk = (v, p) => {
    if (typeof v === "string") {
      for (const m of v.matchAll(/https?:\/\/[^\s"'<>)]+/g)) {
        const why = blockedReason(m[0], extraBlockedHosts);
        if (why) hits.push({ path: p, url: m[0], why });
      }
    } else if (Array.isArray(v)) v.forEach((x, i) => walk(x, `${p}[${i}]`));
    else if (v && typeof v === "object") for (const [k, x] of Object.entries(v)) walk(x, `${p}.${k}`);
  };
  walk(value, where);
  return hits;
}





// Guarded fetch. Redirects are followed by hand so every hop is checked before
// it is requested: nothing here may reach Jira, Confluence or any internal tool.
const out = [];
for (const item of $input.all()) {
  const ch = item.json.channel;
  const blocked = item.json.tenant?.guard?.extraBlockedHosts ?? [];
  let body = null, error = null;
  try {
    let at = assertAllowedUrl(ch.searchUrl || ch.url, blocked);
    let res;
    for (let hop = 0; hop < 6; hop++) {
      res = await this.helpers.httpRequest({ url: at, method: 'GET', returnFullResponse: true, disableFollowRedirect: true, ignoreHttpStatusErrors: true, timeout: 30000,
        headers: { 'user-agent': 'Mozilla/5.0 (compatible; ionic-rfp-sweeper/0.2)' } });
      const loc = res.statusCode >= 300 && res.statusCode < 400 ? (res.headers.location || res.headers.Location) : null;
      if (!loc) break;
      at = assertAllowedUrl(new URL(loc, at).href, blocked);
    }
    if (res.statusCode >= 400) error = 'HTTP ' + res.statusCode;
    else body = res.body;
  } catch (e) {
    error = e.message;
  }
  out.push({ json: { ...item.json, body, error } });
}
return out;

/**
 * Normalise whatever a channel returned into one posting shape.
 *
 * Portals differ wildly: some serve JSON, most serve HTML, several are
 * client-rendered and return an empty body to a plain fetch. That last case is
 * not an error and must not be reported as "no opportunities" — it is reported
 * as "needs-browser", which is a different fact.
 *
 * Deliberately crude. The scorer does the deciding, and a per-portal parser is a
 * maintenance burden that rots the moment the portal redesigns.
 *
 * Import-free on purpose: build-workflows.mjs inlines it into the n8n Code nodes.
 */

const ENTITIES = { amp: "&", lt: "<", gt: ">", quot: '"', apos: "'", nbsp: " ", mdash: "—", ndash: "–", rsquo: "'", lsquo: "'", rdquo: '"', ldquo: '"', hellip: "…", eacute: "é", egrave: "è", agrave: "à", ccedil: "ç" };
const decode = (s) => s.replace(/&(#x?[0-9a-f]+|[a-z]+);/gi, (m, e) => {
  if (e[0] === "#") { const n = e[1] === "x" || e[1] === "X" ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10); return Number.isFinite(n) ? String.fromCodePoint(n) : m; }
  return ENTITIES[e.toLowerCase()] ?? m;
});

const blankPosting = (ch) => ({
  sourceId: null, title: "", summary: "", buyer: null, buyerType: null,
  country: ch.country ?? null, closeDate: null, estimatedValue: null, incumbent: null, url: ch.url,
});

/** RFC 4180 CSV: quoted fields, doubled quotes, newlines inside quotes. */
function parseCsv(text) {
  const rows = [];
  let row = [], field = "", q = false;
  const s = String(text).replace(/^\uFEFF/, "");
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (q) {
      if (c === '"') { if (s[i + 1] === '"') { field += '"'; i++; } else q = false; }
      else field += c;
    } else if (c === '"') q = true;
    else if (c === ",") { row.push(field); field = ""; }
    else if (c === "\n" || c === "\r") {
      if (c === "\r" && s[i + 1] === "\n") i++;
      row.push(field); rows.push(row); row = []; field = "";
    } else field += c;
  }
  if (field || row.length) { row.push(field); rows.push(row); }
  const [head, ...data] = rows;
  return data.filter((r) => r.length > 1).map((r) => Object.fromEntries(head.map((h, i) => [h, r[i] ?? ""])));
}

const stripHtml = (h) => decode(String(h ?? "").replace(/<[^>]+>/g, " ")).replace(/\s+/g, " ").trim();

/** Structured feeds: full descriptions, real buyers and closing dates. */
const FORMATS = {
  "canadabuys-csv"(ch, body) {
    return parseCsv(body)
      .filter((r) => !/award|cancel|expired/i.test(r["tenderStatus-appelOffresStatut-eng"] ?? ""))
      .map((r) => {
        const desc = stripHtml(r["tenderDescription-descriptionAppelOffres-eng"]);
        return {
          ...blankPosting(ch),
          sourceId: r["referenceNumber-numeroReference"] || null,
          title: r["title-titre-eng"] || r["title-titre-fra"] || "",
          summary: desc.slice(0, 600),
          body: desc.slice(0, 20000),
          buyer: r["contractingEntityName-nomEntitContractante-eng"] || null,
          buyerType: r["endUserEntitiesName-nomEntitesUtilisateurFinal-eng"] || null,
          closeDate: (r["tenderClosingDate-appelOffresDateCloture"] || "").slice(0, 10) || null,
          url: r["noticeURL-URLavis-eng"] || ch.url,
          publishedDate: (r["publicationDate-datePublication"] || "").slice(0, 10) || null,
          noticeType: r["noticeType-avisType-eng"] || null,
          region: r["regionsOfDelivery-regionsLivraison-eng"] || null,
        };
      });
  },
  "sam-sgs"(ch, body) {
    const results = body?.results ?? body?._embedded?.results ?? [];
    return results
      .filter((r) => !/award|justification|sale of surplus/i.test(r.type?.value ?? ""))
      .map((r) => {
        const desc = stripHtml((r.descriptions ?? []).map((d) => d.content).join(" "));
        const org = (r.organizationHierarchy ?? []).map((o) => o.name).filter(Boolean);
        return {
          ...blankPosting(ch),
          sourceId: r.solicitationNumber || r._id || null,
          title: r.title ?? "",
          summary: desc.slice(0, 600),
          body: desc.slice(0, 20000),
          buyer: org[org.length - 1] ?? org[0] ?? null,
          buyerType: org[0] ?? null,
          closeDate: (r.responseDate ?? "").slice(0, 10) || null,
          url: r._id ? `https://sam.gov/opp/${r._id}/view` : ch.url,
          publishedDate: (r.publishDate ?? "").slice(0, 10) || null,
          noticeType: r.type?.value ?? null,
        };
      });
  },
};

function extractPostings(channel, body, error) {
  const ch = channel ?? {};
  if (!error && FORMATS[ch.format]) {
    try {
      const postings = FORMATS[ch.format](ch, body);
      return { channel: ch.id, status: postings.length ? "ok" : "empty", postings };
    } catch (e) {
      return { channel: ch.id, status: "fetch-failed", detail: `could not parse ${ch.format}: ${e.message}`.slice(0, 300), postings: [] };
    }
  }
  if (error && /^Blocked:/.test(String(error))) return { channel: ch.id, status: "blocked", detail: String(error).slice(0, 300), postings: [] };
  if (error) return { channel: ch.id, status: "fetch-failed", detail: String(error).slice(0, 300), postings: [] };

  // JSON channels (SAM.gov and anything with a real API)
  if (body && typeof body === "object") {
    const rows = body.opportunitiesData ?? body.results ?? body.items ?? [];
    return {
      channel: ch.id,
      status: rows.length ? "ok" : "empty",
      postings: rows.map((r) => ({
        ...blankPosting(ch),
        sourceId: r.noticeId ?? r.id ?? null,
        title: r.title ?? r.name ?? "",
        summary: r.description ?? r.summary ?? "",
        buyer: r.organizationName ?? r.agency ?? r.buyer ?? null,
        closeDate: r.responseDeadLine ?? r.closeDate ?? r.closingDate ?? null,
        estimatedValue: r.awardAmount ?? r.estimatedValue ?? null,
        url: r.uiLink ?? r.url ?? ch.url,
      })),
    };
  }

  const html = String(body ?? "");
  const stripped = html.replace(/<script[\s\S]*?<\/script>/gi, "").replace(/<style[\s\S]*?<\/style>/gi, "");
  const text = stripped.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();

  // A client-rendered portal returns a shell. Say so rather than claiming zero.
  if (text.length < 400 && ch.render === "client") {
    return { channel: ch.id, status: "needs-browser", detail: "client-rendered shell, no server-side content", postings: [] };
  }

  const links = [...stripped.matchAll(/<a[^>]+href="([^"]+)"[^>]*>([\s\S]{3,220}?)<\/a>/gi)];
  const seen = new Set();
  const postings = [];
  for (const [, href, label] of links) {
    const title = decode(label.replace(/<[^>]+>/g, " ")).replace(/\s+/g, " ").trim();
    if (title.length < 12 || seen.has(title)) continue;
    seen.add(title);
    let url;
    try { url = new URL(href, ch.url).href; } catch (e) { continue; }
    postings.push({ ...blankPosting(ch), title, buyer: ch.buyer ?? null, buyerType: ch.buyerType ?? null, url });
  }
  return { channel: ch.id, status: postings.length ? "ok" : "empty", postings };
}

/** Links on a buyer's own site that probably lead to its procurement page. */
function procurementLinks(baseUrl, html, limit = 2) {
  const out = [];
  const re = /<a[^>]+href="([^"]+)"[^>]*>([\s\S]{2,120}?)<\/a>/gi;
  const want = /\b(rfp|rfq|rfi|tenders?|procurement|bids?|bidding|purchasing|solicitations?|opportunities)\b/i;
  for (const [, href, label] of String(html ?? "").matchAll(re)) {
    const text = label.replace(/<[^>]+>/g, " ");
    if (!want.test(text) && !want.test(href)) continue;
    try {
      const u = new URL(href, baseUrl);
      if (!/^https?:$/.test(u.protocol) || out.includes(u.href)) continue;
      out.push(u.href);
    } catch (e) { /* skip */ }
    if (out.length >= limit) break;
  }
  return out;
}





return $input.all().map((item) => ({ json: { ...item.json, body: undefined, extracted: extractPostings(item.json.channel, item.json.body, item.json.error) } }));

