/**
 * Shared scorer. One implementation, used by the CLI, the dashboard and pasted verbatim into the
 * n8n "Score" Code node, so a bid scored on the desk and a bid scored by the
 * scheduled run get the same number.
 *
 * The weights come from the industry pack, never from here. This file decides HOW
 * each dimension is measured; the pack decides how much each one counts.
 *
 * Every score carries its reasons. A number with no reason attached is a number
 * nobody argues with, which means nobody trusts it.
 */

const lower = (s) => String(s ?? "").toLowerCase();

/**
 * Which needles appear in the haystack, as whole words. Substring matching was
 * wrong on the first live run: "SIS" matched "Mississippi".
 */
const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
function matches(haystack, needles) {
  const h = lower(haystack);
  return (needles ?? []).filter((n) => new RegExp(`(^|[^a-z0-9])${esc(lower(n))}($|[^a-z0-9])`).test(h));
}

/**
 * Hard gate. Runs before scoring. A disqualifier hit means the item never
 * reaches the score, so a bus-routing tender cannot accumulate points for
 * having a close date and a named buyer.
 */
function disqualify(item, pack) {
  const text = `${item.title ?? ""} ${item.summary ?? ""}`;
  const hits = matches(text, pack.disqualifiers);
  if (hits.length === 0) return null;

  // A disqualifier inside the body but a strong qualifier in the title is a
  // judgement call, not an automatic kill. Flag it rather than dropping it.
  const titleHits = matches(item.title, pack.disqualifiers);
  const titleQualifiers = matches(item.title, pack.qualifiers?.titleKeywords);
  if (titleHits.length === 0 && titleQualifiers.length > 0) {
    return { kind: "flag", reason: `body mentions ${hits.join(", ")} but the title qualifies` };
  }
  return { kind: "drop", reason: `disqualified on ${hits.join(", ")}` };
}

/**
 * Each dimension returns 0..1. The pack's weight turns it into points.
 * Unknown is NOT zero. An item with no close date scores 0.5 on timeline and
 * says so, rather than being punished for a field the portal did not publish.
 */
const DIMENSIONS = {
  productFit(item, pack) {
    const t = matches(item.title, pack.qualifiers?.titleKeywords);
    const b = matches(`${item.summary ?? ""} ${item.body ?? ""}`, pack.qualifiers?.bodyKeywords);
    if (t.length === 0 && b.length === 0) {
      return { v: 0, why: "no qualifier matched" };
    }
    // A title match is worth far more than a body match. Portals pad the body.
    const v = Math.min(1, t.length * 0.4 + b.length * 0.08);
    return { v, why: `title: ${t.join(", ") || "none"}; body: ${b.length} match(es)` };
  },

  buyerFit(item, pack) {
    const hits = matches(`${item.buyer ?? ""} ${item.buyerType ?? ""}`, pack.buyerTypes);
    if (hits.length > 0) return { v: 1, why: `buyer type: ${hits[0]}` };
    if (!item.buyer) return { v: 0.5, why: "buyer not published, unknown" };
    return { v: 0.2, why: "buyer does not match a listed type" };
  },

  dealSize(item, pack) {
    const v = item.estimatedValue;
    if (v == null) return { v: 0.5, why: "value not published, unknown" };
    const floors = (pack.thresholds?.values ?? []).map((t) => t.amount).filter(Boolean);
    const floor = floors.length ? Math.min(...floors) : 75000;
    if (v < floor) return { v: 0.2, why: `below the ${floor} posting floor` };
    if (v < floor * 4) return { v: 0.6, why: `modest: ${v}` };
    return { v: 1, why: `material: ${v}` };
  },

  timeline(item) {
    if (!item.closeDate) return { v: 0.5, why: "close date not published, unknown" };
    const days = Math.round((new Date(item.closeDate) - new Date()) / 86400000);
    if (days < 0) return { v: 0, why: `closed ${-days} days ago` };
    if (days <= 7) return { v: 0.25, why: `${days} days left, too short to run a real response` };
    if (days <= 21) return { v: 0.7, why: `${days} days left` };
    return { v: 1, why: `${days} days left` };
  },

  incumbent(item) {
    if (item.incumbent) return { v: 1, why: `incumbent named: ${item.incumbent}` };
    if (matches(`${item.title} ${item.summary}`, ["replace", "replacement", "legacy", "end of life", "modernization", "modernisation"]).length) {
      return { v: 0.8, why: "replacement language in the posting" };
    }
    return { v: 0.5, why: "no incumbent signal" };
  },

  geography(item, pack, tenant) {
    const geo = tenant?.geography ?? pack.geography ?? [];
    if (!item.country) return { v: 0.5, why: "country not published, unknown" };
    if (geo.includes(item.country)) return { v: 1, why: `${item.country} is in scope` };
    return { v: 0, why: `${item.country} is out of scope` };
  },
};

/**
 * Dimensions where a zero is fatal regardless of the total.
 *
 * Found by test, not by design: a K-12 ERP bid that closed five days ago still
 * scored 81 and would have been marked pursue, because the other five dimensions carried
 * it. Weighting cannot express "this one is a gate" — 10 points of timeline
 * against 90 points of everything else will always lose that argument. So these
 * two are checked separately, after scoring, and they veto.
 */
const VETO = {
  timeline: "the solicitation has already closed",
  geography: "the buyer is outside the tenant's geography",
};

function score(item, pack, tenant) {
  const dq = disqualify(item, pack);
  if (dq?.kind === "drop") {
    return { total: 0, band: "dropped", reasons: [dq.reason], flags: [] };
  }

  // Relevance gate. A posting that matches no qualifier at all is not a finding,
  // however much "unknown" credit it would collect. Found on the first live run:
  // portal nav links ("Terms of Service", "Create an account") scored 38 on
  // unknowns alone and flooded the review list.
  // A title hit, or at least two distinct supporting terms in the description.
  // One stray body word ("delivery" in a parts order) is not relevance.
  const titleHits = matches(item.title, pack.qualifiers?.titleKeywords);
  const bodyHits = matches(`${item.summary ?? ""} ${item.body ?? ""}`, [...(pack.qualifiers?.titleKeywords ?? []), ...(pack.qualifiers?.bodyKeywords ?? [])]);
  if (titleHits.length === 0 && bodyHits.length < 2) {
    return { total: 0, band: "dropped", reasons: [`not relevant: title matched nothing and the description matched ${bodyHits.length ? `only "${bodyHits[0]}"` : "nothing"}`], flags: [] };
  }

  const weights = pack.scoring?.weights ?? {};
  const reasons = [];
  const flags = dq?.kind === "flag" ? [dq.reason] : [];
  let total = 0;
  let unknowns = 0;
  const vetoes = [];

  for (const [name, weight] of Object.entries(weights)) {
    const fn = DIMENSIONS[name];
    if (!fn) {
      flags.push(`pack weights an unknown dimension "${name}"; it scored 0`);
      continue;
    }
    const { v, why } = fn(item, pack, tenant);
    if (/unknown/.test(why)) unknowns += 1;
    if (v === 0 && VETO[name]) vetoes.push(`${VETO[name]} (${why})`);
    total += v * weight;
    reasons.push(`${name} ${Math.round(v * weight)}/${weight} — ${why}`);
  }

  total = Math.round(total);
  const min = pack.scoring?.minScoreToPursue ?? 55;
  const floor = pack.scoring?.autoNoBidBelow ?? 30;

  let band;
  if (total < floor) band = "no bid";
  else if (total < min) band = "review";
  else band = "pursue";

  // A veto wins over the total, always. Reported with the score intact so a
  // reviewer can see it was a good fit that arrived too late or in the wrong
  // country, rather than a bad fit.
  if (vetoes.length) {
    band = "no bid";
    reasons.unshift(`VETOED: ${vetoes.join("; ")}`);
  }

  // Honesty rule: a score built mostly on unknowns is not a confident score,
  // whatever the number says. Never mark one "pursue" on its own say-so.
  if (unknowns >= 3 && band === "pursue" && vetoes.length === 0) {
    band = "review";
    flags.push(`${unknowns} dimensions were unknown; downgraded to review rather than pursue`);
  }

  return { total, band, reasons, flags, unknowns, vetoes };
}




/**
 * The drafter. Turns a scored posting into a finding a person can act on:
 *
 *   - a bid/no-bid brief: what, who, when, the score and why, and what is unknown
 *   - a first-draft response skeleton built from the tenant's own profile and the
 *     product lines it sells into this industry
 *   - a set of action items with due dates worked back from the close date
 *
 * Action items are shown in the dashboard and the Excel "Actions" sheet. They are
 * never created as Jira issues or tasks anywhere.
 *
 * The draft is a starting point, not a submission. Every capability statement in
 * it is taken from tenant.profile, which a person wrote; nothing is invented.
 *
 * Import-free on purpose: build-workflows.mjs inlines it into the n8n Code nodes.
 */

const DAY = 86400000;

/** FNV-1a, twice, for a stable short id without needing a crypto module. */
function hash(s) {
  let a = 0x811c9dc5, b = 0x01000193 ^ 0x5bd1e995;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    a = Math.imul(a ^ c, 0x01000193) >>> 0;
    b = Math.imul(b ^ c, 0x5bd1e995) >>> 0;
  }
  return (a.toString(16).padStart(8, "0") + b.toString(16).padStart(8, "0")).slice(0, 12);
}

const norm = (s) => String(s ?? "").toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();

/**
 * Same posting, same id, whichever portal it was found on. Title plus buyer
 * rather than URL, because one solicitation is often mirrored on two portals.
 */
function findingId(tenantId, posting) {
  const key = posting.sourceId ? `src:${posting.sourceId}` : `${norm(posting.title)}|${norm(posting.buyer)}`;
  return `${tenantId.slice(0, 4)}-${hash(key)}`;
}

const DATE_NAMES = { closing: "Closing", questions: "Questions deadline", preBid: "Pre-bid meeting", siteVisit: "Site visit", award: "Expected award" };

const parseDate = (d) => {
  if (!d) return null;
  const t = new Date(d);
  return Number.isNaN(t.getTime()) ? null : t;
};
const iso = (d) => (d ? d.toISOString().slice(0, 10) : null);

/** Work a due date back from the close date, never earlier than tomorrow. */
function dueBefore(close, daysBefore, fallbackDaysFromNow, now) {
  const floor = new Date(now.getTime() + DAY);
  if (!close) return iso(new Date(now.getTime() + fallbackDaysFromNow * DAY));
  const d = new Date(close.getTime() - daysBefore * DAY);
  return iso(d < floor ? floor : d);
}

function actionsFor(band, close, assignee, now, dates = {}) {
  const mk = (key, title, due) => ({ id: key, title, due, assignee, done: false, source: "drafter", rev: 0 });
  const before = (d, n) => { const t = parseDate(d); return t ? dueBefore(t, n, 1, now) : null; };
  if (band === "review") {
    return [mk("triage", "Triage: read the posting and decide pursue or pass", dueBefore(close, 21, 3, now))];
  }
  const dated = [
    dates.questions && mk("questions", `Send clarification questions before the Q&A deadline (${dates.questions})`, before(dates.questions, 1)),
    dates.preBid && mk("prebid", `Attend the pre-bid meeting (${dates.preBid})`, before(dates.preBid, 0)),
    dates.siteVisit && mk("sitevisit", `Attend the site visit (${dates.siteVisit})`, before(dates.siteVisit, 0)),
  ].filter(Boolean);
  return [...dated,
    mk("read", "Read the full solicitation, addenda and Q&A deadline", dueBefore(close, 25, 2, now)),
    mk("gonogo", "Go / no-go decision with a named sponsor", dueBefore(close, 21, 5, now)),
    mk("compliance", "Build the submission compliance checklist (forms, insurance, references, format)", dueBefore(close, 18, 7, now)),
    mk("draft", "Complete the response draft from the drafter skeleton", dueBefore(close, 7, 14, now)),
    mk("review", "Internal review and pricing sign-off", dueBefore(close, 3, 18, now)),
    mk("submit", "Submit and record the confirmation", dueBefore(close, 1, 21, now)),
  ].sort((a, b) => String(a.due).localeCompare(String(b.due)));
}

function bullet(xs) {
  return xs.filter(Boolean).map((x) => `- ${x}`).join("\n");
}

function brief(p, s, pack, tenant, close, now) {
  const days = close ? Math.round((close - now) / DAY) : null;
  const unknown = s.reasons.filter((r) => /unknown/.test(r)).map((r) => r.split(" — ")[0].split(" ")[0]);
  return [
    `${p.title}`,
    `Buyer: ${p.buyer ?? "not published"}${p.country ? ` (${p.country})` : ""}`,
    `Closes: ${close ? `${iso(close)}, ${days} days from today` : "not published"}`,
    `Value: ${p.estimatedValue ?? "not published"}`,
    `Score: ${s.total}/100 — ${s.band} (${pack.name}${pack.status !== "proven" ? `, pack is ${pack.status}` : ""})`,
    "",
    "Why it scored this way:",
    bullet(s.reasons),
    s.flags.length ? `\nFlags:\n${bullet(s.flags)}` : "",
    p.keyDates && Object.keys(p.keyDates).length ? `\nKey dates from the posting page:\n${bullet(Object.entries(p.keyDates).map(([k, v]) => `${DATE_NAMES[k] ?? k}: ${v}`))}` : "",
    p.requirements?.length ? `\n${p.requirements.length} mandatory requirement statement(s) found on the posting page — see the Compliance sheet.` : "",
    p.competitors?.length ? `\nCompetitors named on the posting page: ${p.competitors.join(", ")}` : "",
    p.incumbent ? `\nIncumbent: ${p.incumbent}` : "",
    unknown.length ? `\nUnknown until someone reads the solicitation: ${unknown.join(", ")}` : "",
    `\nSource: ${p.url}`,
  ].filter((x) => x !== "").join("\n");
}

/** Response skeleton. Exported so the dashboard can draft a "review" finding on request. */
function draftResponse(p, pack, tenant, library = []) {
  const prof = tenant.profile ?? {};
  const o = pack.offering ?? {};
  const company = prof.companyName || tenant.name;
  const products = o.productLines?.length ? o.productLines.join(", ") : "[product lines not configured for this industry]";
  const matched = (pack.qualifiers?.titleKeywords ?? []).filter((k) => String(p.title).toLowerCase().includes(k.toLowerCase()));
  const TODO = (x) => `[TODO: ${x}]`;

  return `# Response draft — ${p.title}

Prepared for: ${p.buyer ?? TODO("buyer name")}
Prepared by: ${company}
Status: FIRST DRAFT generated by the RFP drafter. Not reviewed. Do not submit as is.

## 1. Cover letter

${p.buyer ?? TODO("buyer")} is seeking ${matched.length ? matched.join(", ") : TODO("the scope in the buyer's own words")}. ${company} ${prof.oneLiner || TODO("one-sentence description of the company from tenant.profile.oneLiner")}

We are pleased to submit this response and confirm our intent to meet the requirements set out in the solicitation. ${TODO("confirm addenda acknowledged, validity period, signatory")}

## 2. Executive summary

${o.pitch || prof.summary || TODO("two or three paragraphs: the buyer's problem, our solution, the outcome. Source: tenant.profile.summary or offerings.<industry>.pitch")}

Proposed solution: ${products}

## 3. Understanding of requirements

${TODO("restate each mandatory requirement from the solicitation, in the buyer's numbering, before answering it")}
${p.requirements?.length ? `\nMandatory statements found on the posting page (verify against the full solicitation and addenda):\n${bullet(p.requirements.slice(0, 25).map((r) => `${r.id} [${r.kind}] ${r.text}`))}` : ""}
${matched.length ? `\nThe posting title signals: ${matched.join(", ")}.` : ""}
${p.summary ? `\nPosting summary: ${p.summary.slice(0, 600)}` : ""}

## 4. Proposed solution

${bullet((prof.capabilities ?? []).map((c) => c)) || TODO("capabilities mapped to requirements; list in tenant.profile.capabilities")}

## 5. Implementation approach

${prof.implementationApproach || TODO("phases, timeline, governance, data migration, training; source tenant.profile.implementationApproach")}

## 6. Why ${company}

${bullet(prof.differentiators ?? []) || TODO("differentiators; list in tenant.profile.differentiators")}

## 7. Answers from the library

${library.length ? library.map((l) => `### ${l.question}\n[library:${l.id}${l.lastReviewed ? `, reviewed ${l.lastReviewed}` : ""}${l.owner ? `, owner ${l.owner}` : ""}]${l.stale ? " [STALE — confirm with the owner before use]" : ""}\n\n${l.answer || TODO("library entry has no answer text")}`).join("\n\n") : TODO("no library answers matched; add approved answers to library/" + tenant.id + ".json")}
${p.competitors?.length ? `\n## Competitive notes\n\nNamed on the posting page: ${p.competitors.join(", ")}. ${TODO("how we differ, stated only from approved claims")}\n` : ""}
## 8. References

${TODO(`${prof.referencesNote || "select references from customers in this industry who run the proposed product lines; confirm each has agreed"}`)}

## 9. Questions to clarify with the buyer

${bullet([
    !p.closeDate && "Confirm the closing date and time.",
    !p.keyDates?.questions && "Confirm the deadline for questions.",
    p.estimatedValue == null && "Is a budget or price range published?",
    !p.incumbent && "Is there an incumbent system or provider, and when does that contract end?",
    "Submission method, format and page limits.",
  ])}

## 10. Pricing

${TODO("pricing is never drafted automatically")}
`;
}

/**
 * Build a finding from a posting and its score. `pack` is the effective pack
 * (lib/pack.mjs effectivePack), so it carries the tenant's offering.
 */
function draftFinding(posting, s, pack, tenant, channelId, now = new Date(), library = []) {
  const close = parseDate(posting.closeDate);
  const assignee = pack.offering?.defaultAssignee ?? tenant.owners?.default ?? "";
  return {
    id: findingId(tenant.id, posting),
    tenant: tenant.id,
    industry: pack.id,
    industryStatus: pack.status,
    title: posting.title,
    buyer: posting.buyer ?? null,
    country: posting.country ?? null,
    url: posting.url,
    channel: channelId,
    closeDate: iso(close),
    publishedDate: posting.publishedDate ?? null,
    noticeType: posting.noticeType ?? null,
    estimatedValue: posting.estimatedValue ?? null,
    score: s.total,
    band: s.band,
    reasons: s.reasons,
    flags: s.flags,
    draft: { brief: brief(posting, s, pack, tenant, close, now), response: s.band === "pursue" ? draftResponse(posting, pack, tenant, library) : null },
    // Left blank unless the tenant opts into autoAssign: a person assigns it, in the
    // dashboard or the spreadsheet. The suggestion is shown beside the empty field.
    assignee: tenant.autoAssign ? assignee : "",
    suggestedAssignee: assignee,
    actions: actionsFor(s.band, close, tenant.autoAssign ? assignee : "", now, posting.keyDates),
    keyDates: posting.keyDates ?? {},
    requirements: posting.requirements ?? [],
    competitors: posting.competitors ?? [],
    incumbent: posting.incumbent ?? null,
    contentHash: posting.contentHash ?? null,
    libraryMatches: library.map((l) => ({ id: l.id, stale: l.stale })),
  };
}




/**
 * Read a posting's own public page and pull out what the listing did not say.
 *
 * Portal listings give a title and a link. The detail page usually carries the
 * closing date, the question deadline, pre-bid meetings, mandatory requirements
 * and sometimes the incumbent. Reading it turns "unknown" dimensions into real
 * ones, which is the single biggest improvement to score quality.
 *
 * Also produces a content hash, so the next sweep can tell when an addendum or
 * change has been posted (a missed addendum can make a bid non-compliant).
 *
 * Deterministic and import-free: build-workflows.mjs inlines it into n8n.
 */

const MONTHS = { jan: 0, feb: 1, mar: 2, apr: 3, may: 4, jun: 5, jul: 6, aug: 7, sep: 8, sept: 8, oct: 9, nov: 10, dec: 11 };

function pageText(html) {
  return String(html ?? "")
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<(br|\/p|\/div|\/li|\/tr|\/h\d)[^>]*>/gi, "\n")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/g, " ").replace(/&amp;/g, "&").replace(/&#39;|&rsquo;/g, "'").replace(/&quot;/g, '"')
    .replace(/[ \t]+/g, " ")
    .replace(/\n\s*\n+/g, "\n")
    .trim();
}

function fnv(s) {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 0x01000193) >>> 0;
  return h.toString(16).padStart(8, "0");
}

/** Hash of the page's meaningful text. Digits in "page generated at" noise are the usual false alarm, so timestamps are stripped. */
function contentHash(text) {
  const norm = String(text).toLowerCase().replace(/\b\d{1,2}:\d{2}(:\d{2})?\s*(am|pm)?\b/g, "").replace(/\s+/g, " ").trim();
  return `${fnv(norm)}${fnv(norm.split("").reverse().join(""))}`;
}

/** Parse the earliest date in a snippet: 2026-10-15, 15/10/2026, October 15, 2026, 15 October 2026, Oct. 15 2026. */
function parseDateIn(s) {
  const month = (w) => MONTHS[w.slice(0, 4).toLowerCase()] ?? MONTHS[w.slice(0, 3).toLowerCase()];
  const found = [];
  for (const m of s.matchAll(/\b(20\d{2})[-/.](\d{1,2})[-/.](\d{1,2})\b/g)) found.push([m.index, isoDate(+m[1], +m[2] - 1, +m[3])]);
  for (const m of s.matchAll(/\b([A-Za-z]{3,9})\.?\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(20\d{2})\b/g)) if (month(m[1]) != null) found.push([m.index, isoDate(+m[3], month(m[1]), +m[2])]);
  for (const m of s.matchAll(/\b(\d{1,2})(?:st|nd|rd|th)?\s+([A-Za-z]{3,9})\.?,?\s+(20\d{2})\b/g)) if (month(m[2]) != null) found.push([m.index, isoDate(+m[3], month(m[2]), +m[1])]);
  for (const m of s.matchAll(/\b(\d{1,2})\/(\d{1,2})\/(20\d{2})\b/g)) {
    // Ambiguous d/m vs m/d: if the first part cannot be a month, it is the day.
    const [x, y] = [+m[1], +m[2]];
    found.push([m.index, x > 12 ? isoDate(+m[3], y - 1, x) : isoDate(+m[3], x - 1, y)]);
  }
  return found.filter(([, d]) => d).sort((p, q) => p[0] - q[0])[0]?.[1] ?? null;
}
function isoDate(y, mo, d) {
  const t = new Date(Date.UTC(y, mo, d));
  return t.getUTCFullYear() === y && t.getUTCMonth() === mo && t.getUTCDate() === d ? t.toISOString().slice(0, 10) : null;
}

const DATE_LABELS = {
  closing: /(closing|close|due|submission|deadline for (proposals|submissions|bids)|proposals? (are )?due|bid closing)\s*(date|time)?/i,
  questions: /(question|inquir|enquir|clarification)s?\s*(period\s*)?(deadline|due|close|cut-?off|must be (received|submitted))/i,
  preBid: /(pre-?bid|pre-?proposal|bidders'?)\s*(meeting|conference|call)/i,
  siteVisit: /site\s*(visit|tour|meeting)/i,
  award: /(anticipated|expected|estimated)\s*(contract\s*)?(award|start)/i,
};

/** Look for each labelled date within a short window after its label. */
function keyDates(text) {
  const out = {};
  for (const [key, re] of Object.entries(DATE_LABELS)) {
    const g = new RegExp(re.source, "gi");
    let m;
    while ((m = g.exec(text))) {
      // Only the rest of this line: a date on the next line belongs to another label.
      const d = parseDateIn(text.slice(m.index, m.index + m[0].length + 90).split("\n")[0]);
      if (d) { out[key] = d; break; }
    }
  }
  return out;
}

/** Sentences that state a mandatory requirement: the start of a compliance matrix. */
function requirements(text, limit = 60) {
  const sentences = String(text).split(/(?<=[.;:])\s+|\n+/).map((s) => s.trim()).filter((s) => s.length >= 25 && s.length <= 400);
  const re = /\b(shall|must|is required to|are required to|mandatory|will be disqualified|at a minimum|no later than|page limit|must not exceed|submit (one|two|three|\d+) (copies|originals))\b/i;
  const kind = (s) =>
    /insurance|liability|bond|wsib|workers'? comp/i.test(s) ? "insurance" :
    /page|font|format|copies|pdf|electronic|envelope|label/i.test(s) ? "format" :
    /reference|experience|years/i.test(s) ? "experience" :
    /sign|form|appendix|schedule|attach|certif|declaration/i.test(s) ? "form" :
    /price|pricing|cost|fee/i.test(s) ? "pricing" : "technical";
  const seen = new Set();
  const out = [];
  for (const s of sentences) {
    if (!re.test(s)) continue;
    const k = s.toLowerCase().slice(0, 80);
    if (seen.has(k)) continue;
    seen.add(k);
    // Id from the text, not the position, so a person's owner/status on a
    // requirement survives an addendum that inserts a new one above it.
    out.push({ id: `R-${fnv(k + s.length)}`.slice(0, 8), text: s, kind: kind(s) });
    if (out.length >= limit) break;
  }
  return out;
}

/** Competitors named in the page: tenant.competitors = [{ name, aliases: [] }]. */
function competitorMentions(text, competitors) {
  const t = String(text).toLowerCase();
  return (competitors ?? [])
    .filter((c) => [c.name, ...(c.aliases ?? [])].some((n) => n && new RegExp(`(^|[^a-z0-9])${n.toLowerCase().replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}($|[^a-z0-9])`).test(t)))
    .map((c) => c.name);
}

/** Incumbent phrasing: "currently uses X", "the incumbent is X", "existing X system". */
function incumbentHint(text) {
  const m = String(text).match(/\b(?:currently uses?|incumbent (?:vendor |provider |system )?is|existing system is|currently (?:running|on))\s+([A-Z][\w&.\- ]{2,40}?)(?=[,.;\n(]| (?:which|that|since|for|and)\b)/);
  return m ? m[1].trim() : null;
}

/** Everything the scorer, drafter and ledger want from one detail page. */
function analyzeDetail(html, tenant) {
  const text = pageText(html);
  const dates = keyDates(text);
  return {
    contentHash: contentHash(text),
    keyDates: dates,
    closeDate: dates.closing ?? null,
    requirements: requirements(text),
    competitors: competitorMentions(text, tenant?.competitors),
    incumbent: incumbentHint(text),
    body: text.slice(0, 20000),
  };
}




/**
 * Answer library: approved, reusable answers a tenant keeps in library/<tenant>.json.
 *
 * The drafter cites matching entries in a response draft, each with its id and
 * review date. An entry past its review date is still shown but marked STALE,
 * because an out-of-date answer submitted with confidence is worse than a gap.
 *
 * Entry: { id, question, answer, tags[], industries[], owner, lastReviewed, reviewEveryDays }
 *
 * Import-free: build-workflows.mjs inlines it into n8n.
 */

const STOP = new Set("the a an and or of to for in on with by is are be will your our you we that this as at from it its their".split(" "));
const words = (s) => String(s ?? "").toLowerCase().split(/[^a-z0-9]+/).filter((w) => w.length > 2 && !STOP.has(w));

function isStale(entry, now = new Date()) {
  if (!entry.lastReviewed) return true;
  const days = (now - new Date(entry.lastReviewed)) / 86400000;
  return days > (entry.reviewEveryDays ?? 180);
}

/** Top library entries for a posting, by keyword overlap, scoped to the industry. */
function matchLibrary(entries, text, industry, limit = 6, now = new Date()) {
  const doc = new Set(words(text));
  return (entries ?? [])
    .filter((e) => !e.industries?.length || e.industries.includes(industry))
    .map((e) => {
      const terms = [...new Set([...words(e.question), ...(e.tags ?? []).flatMap(words)])];
      const hit = terms.filter((w) => doc.has(w));
      return { entry: e, score: terms.length ? hit.length / Math.sqrt(terms.length) : 0, hit };
    })
    .filter((m) => m.hit.length >= 2 || (m.entry.tags ?? []).some((t) => String(text).toLowerCase().includes(String(t).toLowerCase())))
    .sort((a, b) => b.score - a.score)
    .slice(0, limit)
    .map((m) => ({ id: m.entry.id, question: m.entry.question, answer: m.entry.answer, owner: m.entry.owner ?? null, lastReviewed: m.entry.lastReviewed ?? null, stale: isStale(m.entry, now) }));
}





// Score, read each candidate's own posting page (guarded, same as lib/sweep.mjs),
// score again on what the page says, then draft.
const getPage = async (url, blocked) => {
  let at = assertAllowedUrl(url, blocked), res;
  for (let hop = 0; hop < 6; hop++) {
    res = await this.helpers.httpRequest({ url: at, method: 'GET', returnFullResponse: true, disableFollowRedirect: true, ignoreHttpStatusErrors: true, timeout: 30000 });
    const loc = res.statusCode >= 300 && res.statusCode < 400 ? (res.headers.location || res.headers.Location) : null;
    if (!loc) break;
    at = assertAllowedUrl(new URL(loc, at).href, blocked);
  }
  if (res.statusCode >= 400) throw new Error('HTTP ' + res.statusCode);
  return typeof res.body === 'string' ? res.body : null;
};
const out = [];
for (const item of $input.all()) {
  const { pack, tenant, library, extracted: x } = item.json;
  const blocked = tenant?.guard?.extraBlockedHosts ?? [];
  const candidates = [];
  for (const raw of x.postings) {
    const p = { ...raw, url: safeLink(raw.url, blocked) };
    const s = score(p, pack, tenant);
    if (s.band === 'dropped' || s.band === 'no bid') continue;
    candidates.push({ p, s });
  }
  const limit = Math.ceil((tenant.detailPagesPerRun ?? 40) / 4);
  for (const c of candidates.filter((c) => c.p.url).sort((a, b) => b.s.total - a.s.total).slice(0, limit)) {
    try {
      const html = await getPage(c.p.url, blocked);
      if (!html) continue;
      const d = analyzeDetail(html, tenant);
      c.p = { ...c.p, body: d.body, closeDate: c.p.closeDate ?? d.closeDate, incumbent: c.p.incumbent ?? d.incumbent, keyDates: d.keyDates, requirements: d.requirements, competitors: d.competitors, contentHash: d.contentHash };
      c.s = score(c.p, pack, tenant);
    } catch (e) { c.s.flags.push('posting page not read: ' + e.message); }
  }
  const findings = [];
  for (const c of candidates) {
    if (c.s.band === 'dropped' || c.s.band === 'no bid') continue;
    const matched = c.s.band === 'pursue' ? matchLibrary(library ?? [], c.p.title + ' ' + (c.p.body ?? ''), pack.id) : [];
    findings.push(draftFinding({ ...c.p, body: undefined }, c.s, pack, tenant, x.channel, new Date(), matched));
  }
  out.push({ json: { channel: x.channel, status: x.status, detail: x.detail ?? null, found: x.postings.length, findings } });
}
return out;
